//! Packed map32 definitions and their four map16 stores on the live caller
//! clock. Cache hits retain the preceding native work buffer and real frame.
use super::{native_work::{Work, WorkBus}, nmi_stack::{NativeNmiContext, CARRY, ZERO}};
use snes::CpuMasterTimeline;
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct Map32Definition { pc: u16, complete: bool }
impl Default for Map32Definition { fn default() -> Self { Self { pc: 0xf691, complete: false } } }
impl Map32Definition {
    pub(crate) fn complete(&self) -> bool { self.complete }
    pub(crate) fn step(&mut self, cpu: &mut NativeNmiContext, clock: &mut CpuMasterTimeline,
        bus: impl WorkBus) -> Option<u64> {
        if self.complete { return None; }
        assert_eq!((cpu.bank, cpu.pc, cpu.d, cpu.p & 8), (2, self.pc, 0, 0));
        let mut w = Work { cpu, clock, bus, cycles: 0 };
        let pc = self.pc; let m = if w.cpu.p & 0x20 != 0 { 1 } else { 2 };
        let a = w.cpu.a & if m == 1 { 255 } else { 65535 };
        w.fetch();
        self.pc = match pc {
            0xf691 | 0xf6cb | 0xf6dd | 0xf70b | 0xf71d | 0xf74b | 0xf75d | 0xf78b | 0xf79d => { w.drain(6); w.push(a, m); pc + 1 }
            0xf7ad | 0xf6d3 | 0xf6e5 | 0xf713 | 0xf725 | 0xf753 | 0xf765 | 0xf793 | 0xf7a5 => { w.drain(12); let v = w.pull(m); w.load(v, m); pc + 1 }
            0xf692 | 0xf7ae | 0xf6d4 | 0xf6e6 | 0xf714 | 0xf726 | 0xf754 | 0xf766 | 0xf794 | 0xf7a6 => { w.mask(if pc == 0xf692 { 0xfff8 } else if pc == 0xf7ae { 7 } else { 15 }, m); pc + 1 + u16::from(m) }
            0xf695 => { w.drain(16); let v = w.read(w.absolute(0x4440), m);
                w.cpu.p = (w.cpu.p & !CARRY) | u8::from(a >= v); w.flags(a.wrapping_sub(v), m); pc + 3 }
            0xf698 => { if w.branch(w.cpu.p & ZERO == 0) { 0xf69d } else { pc + 2 } }
            0xf69a => { w.drain(16); 0xf7ad }
            0xf69d | 0xf6a1 | 0xf6af | 0xf6b6 | 0xf6bd | 0xf6c4 | 0xf6d0 | 0xf6d6 | 0xf6e2 | 0xf6e8 | 0xf6ef | 0xf6f6 | 0xf6fd | 0xf704 | 0xf710 | 0xf716 | 0xf722 | 0xf728 | 0xf72f | 0xf736 | 0xf73d | 0xf744 | 0xf750 | 0xf756 | 0xf762 | 0xf768 | 0xf76f | 0xf776 | 0xf77d | 0xf784 | 0xf790 | 0xf796 | 0xf7a2 | 0xf7a8 => { w.drain(16);
                let at = match pc { 0xf69d => 0x4440, 0xf6a1 => 0x4442, 0xf6af => 0x4400, 0xf6b6 => 0x4402, 0xf6bd => 0x4404, 0xf6c4 => 0x4406, 0xf6d0 => 0x4401, 0xf6d6 => 0x4403, 0xf6e2 => 0x4405, 0xf6e8 => 0x4407, 0xf6ef => 0x4410, 0xf6f6 => 0x4412, 0xf6fd => 0x4414, 0xf704 => 0x4416, 0xf710 => 0x4411, 0xf716 => 0x4413, 0xf722 => 0x4415, 0xf728 => 0x4417, 0xf72f => 0x4420, 0xf736 => 0x4422, 0xf73d => 0x4424, 0xf744 => 0x4426, 0xf750 => 0x4421, 0xf756 => 0x4423, 0xf762 => 0x4425, 0xf768 => 0x4427, 0xf76f => 0x4430, 0xf776 => 0x4432, 0xf77d => 0x4434, 0xf784 => 0x4436, 0xf790 => 0x4431, 0xf796 => 0x4433, 0xf7a2 => 0x4435, 0xf7a8 => 0x4437, _ => unreachable!() };
                w.write(w.absolute(at), a, m); pc + 3 }
            0xf6a0 | 0xf6a4 | 0xf6cc | 0xf6cd | 0xf6ce | 0xf6cf | 0xf6de | 0xf6df | 0xf6e0 | 0xf6e1 | 0xf70c | 0xf70d | 0xf70e | 0xf70f | 0xf71e | 0xf71f | 0xf720 | 0xf721 | 0xf74c | 0xf74d | 0xf74e | 0xf74f | 0xf75e | 0xf75f | 0xf760 | 0xf761 | 0xf78c | 0xf78d | 0xf78e | 0xf78f | 0xf79e | 0xf79f | 0xf7a0 | 0xf7a1 => { w.drain(6); w.cpu.p = (w.cpu.p & !CARRY) | ((a & 1) as u8); w.load(a >> 1, m); pc + 1 }
            0xf6a5 => { w.drain(16); let v = w.read(w.absolute(0x4442), m); w.adc(v); pc + 3 }
            0xf6a8 | 0xf7b1 => { w.tax_word(); pc + 1 }
            0xf6a9 => { w.width(0x20, false); pc + 2 }
            0xf7ab => { w.width(0x30, true); pc + 2 }
            0xf6ab | 0xf6b2 | 0xf6b9 | 0xf6c0 | 0xf6c7 | 0xf6d9 | 0xf6eb | 0xf6f2 | 0xf6f9 | 0xf700 | 0xf707 | 0xf719 | 0xf72b | 0xf732 | 0xf739 | 0xf740 | 0xf747 | 0xf759 | 0xf76b | 0xf772 | 0xf779 | 0xf780 | 0xf787 | 0xf799 => { w.drain(24);
                let base = match pc { 0xf6ab => 0x38000, 0xf6b2 => 0x38001, 0xf6b9 => 0x38002, 0xf6c0 => 0x38003, 0xf6c7 => 0x38004, 0xf6d9 => 0x38005, 0xf6eb => 0x3b400, 0xf6f2 => 0x3b401, 0xf6f9 => 0x3b402, 0xf700 => 0x3b403, 0xf707 => 0x3b404, 0xf719 => 0x3b405, 0xf72b => 0x48000, 0xf732 => 0x48001, 0xf739 => 0x48002, 0xf740 => 0x48003, 0xf747 => 0x48004, 0xf759 => 0x48005, 0xf76b => 0x4b400, 0xf772 => 0x4b401, 0xf779 => 0x4b402, 0xf780 => 0x4b403, 0xf787 => 0x4b404, 0xf799 => 0x4b405, _ => unreachable!() };
                let v = w.read(base + u32::from(w.cpu.x), m); w.load(v, m); pc + 4 }
            0xf7b2 | 0xf7b7 | 0xf7be | 0xf7c3 => { w.drain(16);
                if w.cpu.p & 0x10 == 0 { w.drain(6); }
                let base = match pc { 0xf7b2 => 0x4400, 0xf7b7 => 0x4420, 0xf7be => 0x4410, _ => 0x4430 };
                let v = w.read(w.absolute(base).wrapping_add(u32::from(w.cpu.x)), m); w.load(v, m); pc + 3 }
            0xf7b5 | 0xf7ba | 0xf7c1 | 0xf7c6 => {
                let at = w.indirect_y_address(if matches!(pc, 0xf7b5 | 0xf7c1) { 0 } else { 3 });
                w.write(at, a, m); pc + 2 }
            0xf7bc | 0xf7bd | 0xf7c8 | 0xf7c9 => { w.increment_y(); pc + 1 }
            0xf7ca => { w.rts(); self.complete = true; w.cpu.pc }
            _ => unreachable!("map32 definition PC {pc:04x}"),
        };
        w.cpu.pc = self.pc; Some(w.cycles)
    }
}
